sp_widget.css:
/* BCE Global Tech login page for the Fun on Platform portals */
.bce-login {
  min-height: 70vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 16px;
  background: linear-gradient(180deg, #e9eff6 0%, #ffffff 70%);
  font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
  color: #1b2733;
}
.bce-login-card {
  width: 100%;
  max-width: 420px;
  background: #fff;
  border-radius: 10px;
  border-top: 6px solid #00549a;
  box-shadow: 0 10px 30px rgba(0, 55, 120, 0.15);
  padding: 32px 32px 24px;
  text-align: center;
}

/* logo slot */
.bce-login-logo { display: flex; justify-content: center; margin-bottom: 24px; }
.bce-login-logo img { max-width: 240px; max-height: 80px; width: auto; height: auto; background: #00549a; }
.bce-login-logo-placeholder {
  width: 240px;
  height: 80px;
  border: 2px dashed #9db8d6;
  border-radius: 8px;
  background: #00549a;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #5b6878;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 13px;
}

/* restyle the embedded platform Login widget */
.bce-login-form { text-align: left; }
.bce-login-form .panel,
.bce-login-form .panel-body { border: 0; box-shadow: none; background: transparent; padding: 0; margin: 0; }
.bce-login-form .panel-heading,
.bce-login-form h2,
.bce-login-form h3,
.bce-login-form h4 { display: none; }            /* the logo heads the card instead */
.bce-login-form label { font-weight: 700; font-size: 13px; color: #1b2733; }
.bce-login-form .form-control {
  height: 42px;
  border-radius: 6px;
  border: 1px solid #b9c5d2;
  box-shadow: none;
  font-size: 15px;
}
.bce-login-form .form-control:focus { border-color: #00549a; box-shadow: 0 0 0 3px rgba(0, 84, 154, 0.2); }
.bce-login-form .btn-primary,
.bce-login-form button[type="submit"] {
  width: 100%;
  height: 44px;
  border-radius: 6px;
  background: #00549a;
  border-color: #00549a;
  font-weight: 700;
  font-size: 16px;
}
.bce-login-form .btn-primary:hover,
.bce-login-form .btn-primary:focus { background: #003778; border-color: #003778; }
.bce-login-form a { color: #00549a; }

.bce-login-help { margin: 20px 0 0; font-size: 13px; color: #5b6878; }

@media (max-width: 480px) {
  .bce-login-card { padding: 24px 20px 20px; }
}

sp_widget.script:
(function($sp) {
    /* BCE Global Tech login page.
     * Logo: upload an image in System UI > Images named "login_logo.png".
     * (Created with the app selected it becomes "x_1802710_fun_on_0.login_logo.png"; both work.)
     * Until then a "Logo" placeholder is shown. */
    var LOGO_NAMES = ['x_1802710_fun_on_0.BCE_color_logo.png', 'login_logo.png'];

    data.logo = '';
    data.logoAlt = 'BCE Global Tech';
    var img = new GlideRecord('db_image');
    img.addQuery('name', 'IN', LOGO_NAMES.join(','));
    img.orderByDesc('sys_updated_on');
    img.setLimit(1);
    img.query();
    if (img.next()) data.logo = '/' + img.getValue('name');


    data.help ='Sign in with the creditinals provided by game organiser';

    // the platform's own Login widget handles authentication and the redirect after sign-in
    data.loginWidget = $sp.getWidget('fun_pdi_login', {});
})();
